def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * drain_voltage_abs - parameters[3] * np.log10(parameters[4] - gate_voltage_abs) - parameters[5] * np.log10(drain_voltage_abs - parameters[6])
